From e91d5f94acf68618ea3ad9c92ac28614e791ae7d Mon Sep 17 00:00:00 2001
From: Jacky Bai <ping.bai@nxp.com>
Date: Fri, 20 Mar 2026 16:43:46 +0800
Subject: [PATCH] pmdomain: imx8mp-blk-ctrl: Keep the NOC_HDCP clock enabled

Keep the NOC_HDCP clock always enabled to fix the potential hang
caused by the NoC ADB400 port power down handshake.

Fixes: 77b0ddb42add ("soc: imx: add i.MX8MP HDMI blk ctrl HDCP/HRV_MWR")
Signed-off-by: Jacky Bai <ping.bai@nxp.com>
Cc: stable@vger.kernel.org
Signed-off-by: Ulf Hansson <ulf.hansson@linaro.org>

diff --git a/drivers/pmdomain/imx/imx8mp-blk-ctrl.c b/drivers/pmdomain/imx/imx8mp-blk-ctrl.c
index 8fc79f9723f0..3f5b9499d30a 100644
--- a/drivers/pmdomain/imx/imx8mp-blk-ctrl.c
+++ b/drivers/pmdomain/imx/imx8mp-blk-ctrl.c
@@ -352,9 +352,6 @@ static void imx8mp_hdmi_blk_ctrl_power_on(struct imx8mp_blk_ctrl *bc,
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(12));
 		regmap_clear_bits(bc->regmap, HDMI_TX_CONTROL0, BIT(3));
 		break;
-	case IMX8MP_HDMIBLK_PD_HDCP:
-		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(11));
-		break;
 	case IMX8MP_HDMIBLK_PD_HRV:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(3) | BIT(4) | BIT(5));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(15));
@@ -408,9 +405,6 @@ static void imx8mp_hdmi_blk_ctrl_power_off(struct imx8mp_blk_ctrl *bc,
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(7));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(22) | BIT(24));
 		break;
-	case IMX8MP_HDMIBLK_PD_HDCP:
-		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(11));
-		break;
 	case IMX8MP_HDMIBLK_PD_HRV:
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(15));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(3) | BIT(4) | BIT(5));
@@ -439,7 +433,7 @@ static int imx8mp_hdmi_power_notifier(struct notifier_block *nb,
 	regmap_write(bc->regmap, HDMI_RTX_CLK_CTL0, 0x0);
 	regmap_write(bc->regmap, HDMI_RTX_CLK_CTL1, 0x0);
 	regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0,
-			BIT(0) | BIT(1) | BIT(10));
+			BIT(0) | BIT(1) | BIT(10) | BIT(11));
 	regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(0));

 	/*
-- 
2.34.1

Based on the commit message, the root cause and the patch provided below, you need to:

1. explain how the bug occurs, including all code statements that are most likely to lead to the bug and why. 
2. explain how the bug is fixed, including code statements fixing the bug and why. 

You must include one or more code statements in point 1 and 2.
Code statements included in point 1 should be as brief as possible, only include the ones that are most related to the root cause and  the number of code statements may not exceed 3.


Here is the commit message:
pmdomain: imx8mp-blk-ctrl: Keep the NOC_HDCP clock enabled

Keep the NOC_HDCP clock always enabled to fix the potential hang
caused by the NoC ADB400 port power down handshake.

Fixes: 77b0ddb42add ("soc: imx: add i.MX8MP HDMI blk ctrl HDCP/HRV_MWR")
Signed-off-by: Jacky Bai <ping.bai@nxp.com>
Cc: stable@vger.kernel.org
Signed-off-by: Ulf Hansson <ulf.hansson@linaro.org>

Here is the root cause:
The bug was caused by dynamically enabling/disabling the NOC_HDCP clock (bit 11) during HDCP power domain transitions in imx8mp_hdmi_blk_ctrl_power_on/power_off. This toggling interfered with the NoC ADB400 port power down handshake, resulting in a potential system hang. Keeping the clock always enabled by removing the dynamic control and setting it in the initialization notifier fixes the issue.

Here is the patch:

 static void imx8mp_hdmi_blk_ctrl_power_on(struct imx8mp_blk_ctrl *bc,
 					  struct imx8mp_blk_ctrl_domain *domain)
 {
 	switch (domain->id) {
 	case IMX8MP_HDMIBLK_PD_IRQSTEER:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(9));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(16));
 		break;
 	case IMX8MP_HDMIBLK_PD_LCDIF:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0,
 				BIT(16) | BIT(17) | BIT(18) |
 				BIT(19) | BIT(20));
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(11));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0,
 				BIT(4) | BIT(5) | BIT(6));
 		regmap_set_bits(bc->regmap, HDMI_TX_CONTROL0,
 				FIELD_PREP(HDMI_LCDIF_NOC_HURRY_MASK, 7));
 		break;
 	case IMX8MP_HDMIBLK_PD_PAI:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(17));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(18));
 		break;
 	case IMX8MP_HDMIBLK_PD_PVI:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(28));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(22));
 		break;
 	case IMX8MP_HDMIBLK_PD_TRNG:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(27) | BIT(30));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(20));
 		break;
 	case IMX8MP_HDMIBLK_PD_HDMI_TX:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0,
 				BIT(2) | BIT(4) | BIT(5));
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1,
 				BIT(12) | BIT(13) | BIT(14) | BIT(15) | BIT(16) |
 				BIT(18) | BIT(19) | BIT(20) | BIT(21));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0,
 				BIT(7) | BIT(10) | BIT(11));
 		regmap_set_bits(bc->regmap, HDMI_TX_CONTROL0, BIT(1));
 		break;
 	case IMX8MP_HDMIBLK_PD_HDMI_TX_PHY:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(7));
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(22) | BIT(24));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(12));
 		regmap_clear_bits(bc->regmap, HDMI_TX_CONTROL0, BIT(3));
 		break;
-	case IMX8MP_HDMIBLK_PD_HDCP:
-		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(11));
-		break;
 	case IMX8MP_HDMIBLK_PD_HRV:
 		regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(3) | BIT(4) | BIT(5));
 		regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(15));
 		break;
 	default:
 		break;
 	}
 }

 static void imx8mp_hdmi_blk_ctrl_power_off(struct imx8mp_blk_ctrl *bc,
 					   struct imx8mp_blk_ctrl_domain *domain)
 {
 	switch (domain->id) {
 	case IMX8MP_HDMIBLK_PD_IRQSTEER:
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(9));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(16));
 		break;
 	case IMX8MP_HDMIBLK_PD_LCDIF:
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0,
 				  BIT(4) | BIT(5) | BIT(6));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(11));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL0,
 				  BIT(16) | BIT(17) | BIT(18) |
 				  BIT(19) | BIT(20));
 		break;
 	case IMX8MP_HDMIBLK_PD_PAI:
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(18));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(17));
 		break;
 	case IMX8MP_HDMIBLK_PD_PVI:
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(22));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(28));
 		break;
 	case IMX8MP_HDMIBLK_PD_TRNG:
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(20));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(27) | BIT(30));
 		break;
 	case IMX8MP_HDMIBLK_PD_HDMI_TX:
 		regmap_clear_bits(bc->regmap, HDMI_TX_CONTROL0, BIT(1));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0,
 				  BIT(7) | BIT(10) | BIT(11));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1,
 				  BIT(12) | BIT(13) | BIT(14) | BIT(15) | BIT(16) |
 				  BIT(18) | BIT(19) | BIT(20) | BIT(21));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL0,
 				  BIT(2) | BIT(4) | BIT(5));
 		break;
 	case IMX8MP_HDMIBLK_PD_HDMI_TX_PHY:
 		regmap_set_bits(bc->regmap, HDMI_TX_CONTROL0, BIT(3));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(12));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(7));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(22) | BIT(24));
 		break;
-	case IMX8MP_HDMIBLK_PD_HDCP:
-		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL0, BIT(11));
-		break;
 	case IMX8MP_HDMIBLK_PD_HRV:
 		regmap_clear_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(15));
 		regmap_clear_bits(bc->regmap, HDMI_RTX_CLK_CTL1, BIT(3) | BIT(4) | BIT(5));
 		break;
 	default:
 		break;
 	}
 }

 static int imx8mp_hdmi_power_notifier(struct notifier_block *nb,
 				      unsigned long action, void *data)
 {
 	struct imx8mp_blk_ctrl *bc = container_of(nb, struct imx8mp_blk_ctrl,
 						 power_nb);

 	if (action != GENPD_NOTIFY_ON)
 		return NOTIFY_OK;

 	/*
 	 * Contrary to other blk-ctrls the reset and clock don't clear when the
 	 * power domain is powered down. To ensure the proper reset pulsing,
 	 * first clear them all to asserted state, then enable the bus clocks
 	 * and then release the ADB reset.
 	 */
 	regmap_write(bc->regmap, HDMI_RTX_RESET_CTL0, 0x0);
 	regmap_write(bc->regmap, HDMI_RTX_CLK_CTL0, 0x0);
 	regmap_write(bc->regmap, HDMI_RTX_CLK_CTL1, 0x0);
 	regmap_set_bits(bc->regmap, HDMI_RTX_CLK_CTL0,
-			BIT(0) | BIT(1) | BIT(10));
+			BIT(0) | BIT(1) | BIT(10) | BIT(11));
 	regmap_set_bits(bc->regmap, HDMI_RTX_RESET_CTL0, BIT(0));

 	/*
 	 * On power up we have no software backchannel to the GPC to
 	 * wait for the ADB handshake to happen, so we just delay for a
 	 * bit. On power down the GPC driver waits for the handshake.
 	 */
 	udelay(5);

 	return NOTIFY_OK;
 }



